def calibration_report(y, p, n_bins):
    # return (brier, expected calibration error, auc by ranks), each rounded to 4 places
    n = len(y)
    brier = sum((pi - yi) ** 2 for yi, pi in zip(y, p)) / n
    groups = [[] for _ in range(n_bins)]
    for yi, pi in zip(y, p):
        groups[min(int(pi * n_bins), n_bins - 1)].append((yi, pi))
    ece = 0.0
    for g in groups:
        if g:
            ece += len(g) / n * abs(sum(pi for _, pi in g) / len(g) - sum(yi for yi, _ in g) / len(g))
    pos = sorted(pi for yi, pi in zip(y, p) if yi == 1)
    neg = sorted(pi for yi, pi in zip(y, p) if yi == 0)
    wins, j, k = 0.0, 0, 0
    for a in pos:
        while j < len(neg) and neg[j] < a:
            j += 1
        k = j
        while k < len(neg) and neg[k] == a:
            k += 1
        wins += j + 0.5 * (k - j)
    auc = wins / (len(pos) * len(neg))
    return (round(brier, 4), round(ece, 4), round(auc, 4))
